recon = {"C100": "11300000"}   # 고객 -> 조정계정
gl, sub = {}, {}
def post(lines):
    if sum(a for _, a in lines) != 0:
        return "F5702 대차 불일치"
    for acct, amt in lines:
        if acct in recon:
            sub[acct] = sub.get(acct, 0) + amt
        g = recon.get(acct, acct)
        gl[g] = gl.get(g, 0) + amt
    return "posted"
print(post([("C100", 1100), ("41000000", -1000), ("22200000", -100)]))
print(post([("C100", 1100), ("41000000", -1000)]))
print(gl)
print(sub)
# posted
# F5702 대차 불일치
# {'11300000': 1100, '41000000': -1000, '22200000': -100}
