def validate(line):
    if line["hkont"][0] in "567" and not line.get("kostl"):
        return "E: " + line["hkont"] + " 는 코스트센터가 필요합니다"
    return "OK"
for l in [dict(hkont="52041000"), dict(hkont="52041000", kostl="CC1000"), dict(hkont="11300000")]:
